WITH latest_breadth AS (SELECT sector, pct_above_50dma, stage2_pct FROM breadth.ma_pct_above WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM breadth.ma_pct_above)),
latest_sector AS (SELECT sector, change_5d, breadth_signal FROM breadth.sector_daily WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM breadth.sector_daily))
SELECT lb.sector, lb.pct_above_50dma, lb.stage2_pct, ls.change_5d, ls.breadth_signal FROM latest_breadth lb JOIN latest_sector ls ON lb.sector = ls.sector ORDER BY lb.stage2_pct DESC, lb.pct_above_50dma DESC LIMIT 10;

